<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title=$kind==='estimates'?'Orçamentos da empresa':'Propostas da empresa';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_sales?kind='.$kind.$q);$hidden=function($action)use($esc,$company_sales_csrf){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_sales_csrf" value="'.$esc($company_sales_csrf).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';};$states=['open'=>'Aberto','accepted'=>'Aceito','declined'=>'Recusado','cancelled'=>'Cancelado','converting'=>'Conversão em andamento','converted'=>'Convertido']; ?>
<section class="company-settings-card"><h1><?= $esc($company_page_title); ?></h1><p>Documentos privados com identidade e destinatário capturados na emissão. Aceitar registra a decisão interna; não representa assinatura eletrônica do cliente.</p><p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_sales?kind='.($kind==='estimates'?'proposals':'estimates'))); ?>"><?= $kind==='estimates'?'Ver propostas':'Ver orçamentos'; ?></a></p>
<?php if($error){?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><p><a href="<?= $esc($url()); ?>">Reabrir lista</a></p><?php } ?>
<?php if($detail){?><h2><?= $kind==='estimates'?'ORC':'PROP'; ?>-<?= str_pad((string)$detail['number'],6,'0',STR_PAD_LEFT); ?></h2><p>Estado: <?= $esc($states[$detail['state']]??$detail['state']); ?></p><p><?= $esc($detail['context']['identity']['legal_name']); ?> · Cliente <?= $esc($detail['context']['recipient']['name']); ?></p><p>Emissão <?= $esc($detail['payload']['date']); ?> · Validade <?= $esc($detail['payload']['due_date']); ?></p><ul><?php foreach($detail['payload']['items'] as $item){?><li><?= $esc($item['description'].' — '.$item['qty'].' × '.$item['rate']); ?><?php foreach($item['taxes'] as $tax){?> · <?= $esc($tax['name'].' '.$tax['rate'].'%'); ?><?php } ?></li><?php } ?></ul><p>Total <?= $esc($detail['context']['currency']['name'].' '.$detail['total']); ?></p><p><?= nl2br($esc($detail['payload']['note'])); ?></p><p><a href="<?= $esc($url('&document='.(int)$detail['id'].'&pdf=1')); ?>">Baixar PDF privado</a></p>
<?php if($detail['state']==='open'){foreach(['accepted'=>'Registrar aceite','declined'=>'Registrar recusa','cancelled'=>'Cancelar documento'] as $action=>$label){if(($action==='cancelled'&&!$can_delete)||($action!=='cancelled'&&!$can_edit))continue;echo form_open($url());$hidden($action);?><input type="hidden" name="document_id" value="<?= (int)$detail['id']; ?>"><button type="submit"><?= $label; ?></button><?= form_close(); ?><?php }} ?>
<?php if(in_array($detail['state'],['accepted','converting'],true)&&$can_edit&&$can_convert){?><?= form_open($url());$hidden('convert'); ?><input type="hidden" name="document_id" value="<?= (int)$detail['id']; ?>"><p>A conversão preserva o documento de origem e emite uma única fatura. Se a identidade, cliente ou configuração mudou, crie outro documento revisado.</p><button type="submit"><?= $detail['state']==='converting'?'Retomar conversão':'Converter em fatura'; ?></button><?= form_close(); ?><?php } ?>
<?php if((int)$detail['invoice_id']>0){?><p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_invoices?invoice='.(int)$detail['invoice_id'])); ?>">Abrir fatura vinculada</a></p><?php } ?><p><a href="<?= $esc($url()); ?>">Voltar à lista</a></p><?php } ?>
<?php if($detail&&$portal_permissions){?><h2>Acesso no portal por contato</h2><p>Autorize somente contatos privados deste cliente. A permissão vale para <?= $kind==='estimates'?'orçamentos':'propostas'; ?> emitidos e aceitos desta empresa; não concede outras permissões nem compartilha contatos.</p><?php foreach($portal_permissions as $contact=>$permission){?><?= form_open($url());$hidden('portal_permission'); ?><input type="hidden" name="document_id" value="<?= (int)$detail['id']; ?>"><input type="hidden" name="contact_id" value="<?= (int)$contact; ?>"><input type="hidden" name="revision" value="<?= $esc($permission['revision']); ?>"><label><input type="checkbox" name="allowed" value="1" <?= $permission['allowed']?'checked':''; ?> <?= $can_contact_edit?'':'disabled'; ?>> <?= $esc($permission['name']); ?></label><?php if($can_contact_edit){?><button type="submit">Salvar acesso no portal</button><?php } ?><?= form_close(); ?><?php }} ?>
<?php require APPPATH.'views/admin/companies/sales_extras.php'; ?>
<h2>Documentos desta empresa</h2><form method="get" action="<?= $esc(CompanyRequestScope::adminUrl($this,'company_sales')); ?>"><input type="hidden" name="kind" value="<?= $esc($kind); ?>"><label for="sales-search">Buscar descrição ou cliente</label><input class="form-control" id="sales-search" name="search" maxlength="191" value="<?= $esc($search); ?>"><button type="submit">Buscar</button></form><table class="table"><thead><tr><th>Número</th><th>Data</th><th>Total</th><th>Estado</th></tr></thead><tbody><?php foreach($directory['items'] as $row){?><tr><td><a href="<?= $esc($url('&document='.(int)$row['id'])); ?>"><?= str_pad((string)$row['number'],6,'0',STR_PAD_LEFT); ?></a></td><td><?= $esc($row['created_at']); ?></td><td><?= $esc($row['total']); ?></td><td><?= $esc($states[$row['state']]??$row['state']); ?></td></tr><?php } ?></tbody></table><?php if($directory['next']!==null){?><a href="<?= $esc($url('&after='.$directory['next'].'&search='.rawurlencode($search))); ?>">Próxima página</a><?php } ?>
<?php if($can_create){?><h2>Emitir <?= $kind==='estimates'?'orçamento':'proposta'; ?></h2><p>Preencha a identidade/endereço da empresa em Definições antes de emitir. Após emissão, os dados são preservados; use cancelamento e nova emissão para corrigir.</p><?= form_open($url());$hidden('create');$recurring_form=false;require APPPATH.'views/admin/companies/sales_form_fields.php'; ?><button type="submit">Emitir documento privado</button><?= form_close(); ?><?php } ?></section>
